   [318]={next_id=319, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝眼神坚定地点了点头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [319]={next_id=320, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你继续向后翻看，里面记录着她对伯基索米历史传说的研究，其中许多文字已经模糊不清。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [320]={next_id=321, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你看不懂的那些，都是用和老师一样的密码进行编写的。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [321]={next_id=322, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的意思是，格蕾沃恩对你们吟游诗人的传承……也十分了解？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [322]={next_id=323, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管我不想认可，但我猜……格蕾沃恩，她在被修格尔侵蚀之前，很可能与我的先辈们有很深的交道。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [323]={next_id=324, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="若是如此……那当年帮助老师和先辈们逃离伯基索米追杀的人，很有可能就是她。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [324]={next_id=325, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而那位谢尔盖将军……也是她当年的幕僚，他在伊凡城对涅普露的呵护和保护……", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [325]={next_id=326, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="也都是格蕾沃恩布置的后手。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [326]={next_id=327, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你和弦枝都沉默了，一个巨大的、关于消灭使徒赛忒的计划，在你们的脑海中逐渐成型。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [327]={next_id=328, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="历史的问题，交给百年之后的人们吧。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [328]={next_id=329, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我想给你看的，是这个。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [329]={next_id=330, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝指着笔记本上夹上书签的那一页。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [330]={next_id=331, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女维雅以自身为祭，化作火鸟，驱散寒灾，拯救了伯基索米。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [331]={next_id=332, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这就是一直流传到现在的版本，但这从来不是真实的故事。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [332]={next_id=333, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赛忒吞噬了这个故事，将这个故事删去了很重要的一部分，因此才能将本被称为祥瑞的火焰神鸟以灾厄的方式具象化。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [333]={next_id=334, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你翻开被标记的书页，在页首有一行娟秀的小字。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [334]={next_id=335, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“牺牲并非美好愿景的结束。”", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [335]={next_id=336, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝站在花田之中，轻声读起笔记里的文字。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [336]={next_id=337, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="很久以前，伯基索米还没有城市，只有散落在大地上的部落。\n灾荒降临，食物耗尽，无数人在严寒与饥饿中死去。\n少年桑斯为了拯救自己的族人，踏上了寻找神明的旅途。\n他希望得到能够终结寒灾，建造一座永远不会有人挨饿的城市。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [337]={next_id=338, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="同一时间，少女维雅也离开了自己的故乡。\n她依照恩师留下的信息寻找神明，\n希望挽救自己的部落，也希望洗清恩师遭受的污名。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [338]={next_id=339, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少年与少女在一处躲避风雪的山洞中相遇。\n于是，他们结伴而行。\n越过吞没旅人的冰河，穿过从不见日光的峡谷。\n最终，两人找到了神明。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [339]={next_id=340, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可神明提出了一个条件：\n必须有一人献出自己的灵魂，才可终结寒灾。\n他们分别走到神明面前，请求成为被献祭的那个人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [340]={next_id=341, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最终，维雅抢先献出了自己的灵魂。\n她在桑斯面前化作火焰，消失在神明的祭台上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [341]={next_id=342, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可那不过是神明的恶作剧，那个所谓的神明，也从未想过拯救任何人。\n心怀愤怒的桑斯举起武器，用它杀死了神明，夺走了神明祭台。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [342]={next_id=343, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当他带着祭台回到故乡时，\n一只沐浴着圣火的不死鸟从祭台中冲出，消除了这场寒灾。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [343]={next_id=344, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桑斯统一了彼此争斗的部落，建立了一座不会让任何人挨饿的城邦。\n为了纪念维雅，他将城邦命名为“维雅格勒”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [344]={next_id=345, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那便是后来维雅格勒的前身。然而，故事并没有在这里结束。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [345]={next_id=346, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桑斯拒绝接受维雅已经永远离开的事实，他离开了自己建立的城市，独自在伯基索米的大地上流浪。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [346]={next_id=347, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝的话语忽然撩拨了你的心弦，冥冥之中，有些细微的丝线逐渐连接了起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [347]={next_id=348, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="传说，维雅破碎的灵魂化作了一朵朵燃烧的鲜花，散落在群山、冰川与河流之间。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [348]={next_id=349, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桑斯用尽余生寻找那些火焰之花。\n当找齐了所有花朵后，他便用自己的心头血浇灌，\n希望维雅的灵魂重新聚集。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [349]={next_id=350, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的行为感动了伯基索米的大地，维雅在火焰花燃起的大火中重获新生。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [350]={next_id=351, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桑斯带着她回到了两人共同建立的城市。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [351]={next_id=352, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从此，他们再也没有分开。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [352]={next_id=353, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝的声音随风消散，你们不约而同地望向了脚边无数盛开的红花。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [353]={next_id=354, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="散落在伯基索米大地上的灵魂……火焰之花……还有奔波的少年……", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [354]={next_id=355, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="眼前的一切，与笔记中记载的神话严丝合缝地重叠在了一起。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [355]={next_id=356, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你不会告诉我，这些都是巧合吧？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [356]={next_id=357, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="巧合到了这种程度，我很难想象这会是自然产生的。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [357]={next_id=358, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你蹲下身，轻轻触碰其中一朵红花，熟悉的温暖再度回应了你。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
